  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider      = \"prisma-client-js\"\n  binaryTargets = [\"native\", \"debian-openssl-3.0.x\", \"windows\"]\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// Перечисление для статуса объявления\nenum AdStatus {\n  active\n  archived\n}\n\n// Модель продавца\nmodel Seller {\n  id         Int       @id @default(autoincrement())\n  email      String    @unique\n  password   String\n  name       String\n  phone      String?\n  avatar     String?\n  lastSeenAt DateTime?\n  createdAt  DateTime  @default(now())\n  updatedAt  DateTime  @updatedAt\n\n  // Связи\n  ads          Ad[]\n  buyerChats   Chat[]    @relation(\"BuyerChats\")\n  sellerChats  Chat[]    @relation(\"SellerChats\")\n  sentMessages Message[]\n\n  @@map(\"sellers\")\n}\n\n// Модель объявления\nmodel Ad {\n  id          Int      @id @default(autoincrement())\n  title       String\n  description String?\n  price       Float?\n  currency    String   @default(\"RUB\")\n  category    String\n  city        String\n  address     String?\n  latitude    Float?\n  longitude   Float?\n  status      AdStatus @default(active)\n  photos      String[] // Массив URL фото\n  sellerId    Int\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  // Связи\n  seller      Seller         @relation(fields: [sellerId], references: [id], onDelete: Cascade)\n  chats       Chat[]\n  attachments AdAttachment[]\n\n  @@map(\"ads\")\n}\n\n// Модель чата\nmodel Chat {\n  id        Int      @id @default(autoincrement())\n  buyerId   Int\n  sellerId  Int\n  adId      Int\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Связи\n  buyer    Seller    @relation(\"BuyerChats\", fields: [buyerId], references: [id])\n  seller   Seller    @relation(\"SellerChats\", fields: [sellerId], references: [id])\n  ad       Ad        @relation(fields: [adId], references: [id])\n  messages Message[]\n\n  @@unique([buyerId, sellerId, adId])\n  @@map(\"chats\")\n}\n\n// Модель сообщения\nmodel Message {\n  id          Int      @id @default(autoincrement())\n  chatId      Int\n  senderId    Int\n  content     String\n  messageType String   @default(\"text\") // text, image\n  status      String   @default(\"sent\") // sent, delivered, read\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  // Связи\n  chat        Chat                @relation(fields: [chatId], references: [id], onDelete: Cascade)\n  sender      Seller              @relation(fields: [senderId], references: [id])\n  attachments MessageAttachment[]\n\n  @@map(\"messages\")\n}\n\n// Модель вложения объявления\nmodel AdAttachment {\n  id       Int    @id @default(autoincrement())\n  adId     Int\n  fileUrl  String\n  fileName String\n  fileType String\n  fileSize Int?\n\n  ad Ad @relation(fields: [adId], references: [id], onDelete: Cascade)\n\n  @@map(\"ad_attachments\")\n}\n\n// Модель вложения сообщения\nmodel MessageAttachment {\n  id        Int    @id @default(autoincrement())\n  messageId Int\n  fileUrl   String\n  fileName  String\n  fileType  String\n  fileSize  Int?\n\n  message Message @relation(fields: [messageId], references: [id], onDelete: Cascade)\n\n  @@map(\"message_attachments\")\n}\n",
